static lstr L1243 = {0, 19598, "// std/internal/async. Tasks and their handles (D109 items 1 and 2).\012//\012// A task frame starts with this header; the value slot and the body's\012// variables follow it (emitasync.nra). The frame is the handle: Async<T> is a\012// narra_task*, and copies of a handle share the frame.\012//\012// Who holds a reference: each copy of the handle, each task in a waiter list,\012// and the loop until the task finishes. release releases what the frame holds\012// at its state, or the value once the task is done; the frame itself is freed\012// when the count reaches zero.\012typedef struct narra_task narra_task;\012typedef struct narra_task_callback narra_task_callback;\012struct narra_task {\012  int64_t rc;\012  // The resume point: 0 before the first run, then the await it waits at.\012  int64_t state;\012  bool done;\012  bool cancelled;\012  // Set at exit once release has run for an unfinished frame.\012  bool dropped;\012  // Set when the task that started this one was cancelled then: a suspending\012  // std call of this task returns Err(AsyncError.Cancelled) at once.\012  bool started_cancelled;\012  // Set on the task of a suspending std function (std/async/time) once it\012  // waits in the loop: a cancel of the task awaiting it reaches its wait.\012  bool forwards_cancel;\012  // Set on the task of Async.all: a cancel of it stops there and does not\012  // reach the handles it awaits.\012  bool keeps_inputs;\012  // Set on a step of an async generator (narra_step below): while it is\012  // pending, awaited is its stream.\012  bool is_step;\012  // The unfinished Async.all tasks that were given this handle. Like a then\012  // callback, each observes the handle, so a cancel walk does not cancel it.\012  int64_t observers;\012  void (*resume)(narra_task* task);\012  void (*release)(narra_task* task);\012  // The value slot of the frame, or NULL for an Async<void>.\012  void* value;\012  // The handle this task waits on, the next task waiting on that handle,\012  // and the first task waiting on this one.\012  narra_task* awaited;\012  narra_task* next_waiter;\012  narra_task* waiters;\012  // The ready queue and the loop's list of unfinished tasks.\012  narra_task* next_ready;\012  bool queued;\012  narra_task* next_live;\012  narra_task* previous_live;\012  // The Async.then callbacks, in the order they were registered.\012  narra_task_callback* callbacks;\012  narra_task_callback* last_callback;\012};\012\012// An Async.then callback: a closure that takes the finished handle. Each\012// callback owns a reference to its environment, which release drops. The\012// closure runtime may come later in the C file, so only the struct tag is named.\012struct narra_env;\012struct narra_task_callback {\012  void (*fn)(struct narra_env* env, narra_task* task);\012  struct narra_env* env;\012  void (*release)(struct narra_env* env);\012  narra_task_callback* next;\012};\012\012static void narra_loop_add(narra_task* task);\012static void narra_loop_remove(narra_task* task);\012static void narra_loop_queue(narra_task* task);\012static narra_task* narra_loop_enter(narra_task* task);\012static void narra_loop_leave(narra_task* previous);\012static void narra_task_finish(narra_task* task);\012static void narra_loop_cancel_wait(narra_task* task);\012\012static void narra_task_free(void* pointer) {\012  narra_task* task = pointer;\012  if (!task->dropped) task->release(task);\012  narra_free(task);\012}\012\012static void narra_task_retain(narra_task* task) {\012  task->rc++;\012}\012\012static void narra_task_release(narra_task* task) {\012  if (--task->rc == 0) narra_drop(task, narra_task_free);\012}\012\012// Fills the header of a new frame: one reference for the handle the creation\012// returns and one for the loop until the task finishes.\012static void narra_task_init(\012  narra_task* task,\012  void (*resume)(narra_task*),\012  void (*release)(narra_task*),\012  void* value\012) {\012  task->rc = 2;\012  task->state = 0;\012  task->resume = resume;\012  task->release = release;\012  task->value = value;\012  narra_loop_add(task);\012}\012\012// Runs the body of a new task until it first waits or returns, as a\012// TypeScript async function does, and gives the handle.\012static narra_task* narra_task_start(narra_task* task) {\012  narra_task* previous = narra_loop_enter(task);\012  task->resume(task);\012  narra_loop_leave(previous);\012  return task;\012}\012\012// The running task waits until handle finishes. The waiter list holds a\012// reference to it. A task cancelled before it waits passes the cancel down\012// the chain now, as Async.cancel does for a task already waiting.\012static void narra_task_wait(narra_task* task, narra_task* handle) {\012  narra_task_retain(task);\012  task->awaited = handle;\012  task->next_waiter = handle->waiters;\012  handle->waiters = task;\012  if (task->cancelled) narra_loop_cancel_wait(task);\012}\012\012// Takes the callbacks off the task and gives them, so a callback that\012// registers or cancels cannot change the list being walked.\012static narra_task_callback* narra_task_take_callbacks(narra_task* task) {\012  narra_task_callback* list = task->callbacks;\012  task->callbacks = NULL;\012  task->last_callback = NULL;\012  return list;\012}\012\012// Runs each callback with the task when run is true, then frees it and\012// releases its environment.\012static void narra_task_run_callbacks(narra_task* task, narra_task_callback* list, bool run) {\012  while (list) {\012    narra_task_callback* callback = list;\012    list = callback->next;\012    if (run) callback->fn(callback->env, task);\012    callback->release(callback->env);\012    narra_free(callback);\012  }\012}\012\012// A callback registered on a finished handle runs on the next loop turn, as\012// in TypeScript: a small task in the ready queue holds it and the handle.\012typedef struct narra_task_later {\012  narra_task h;\012  narra_task* handle;\012  narra_task_callback* callback;\012} narra_task_later;\012\012static void narra_task_later_resume(narra_task* task) {\012  narra_task_later* later = (narra_task_later*)task;\012  narra_task_callback* callback = later->callback;\012  later->callback = NULL;\012  narra_task_run_callbacks(later->handle, callback, true);\012  narra_task_finish(task);\012}\012\012static void narra_task_later_release(narra_task* task) {\012  narra_task_later* later = (narra_task_later*)task;\012  narra_task_run_callbacks(later->handle, later->callback, false);\012  later->callback = NULL;\012  narra_task_release(later->handle);\012}\012\012// Async.then: a cancelled handle drops the callback, a finished one queues it\012// for the next loop turn, and an unfinished one keeps it until it finishes.\012static void narra_task_then(\012  narra_task* task,\012  void (*fn)(struct narra_env*, narra_task*),\012  struct narra_env* env,\012  void (*release)(struct narra_env*)\012) {\012  narra_task_callback* callback = narra_alloc(sizeof(narra_task_callback));\012  callback->fn = fn;\012  callback->env = env;\012  callback->release = release;\012  callback->next = NULL;\012  if (task->cancelled) {\012    narra_task_run_callbacks(task, callback, false);\012    return;\012  }\012  if (task->done) {\012    narra_task_later* later = narra_alloc(sizeof(narra_task_later));\012    memset(later, 0, sizeof(narra_task_later));\012    narra_task_init(&later->h, narra_task_later_resume, narra_task_later_release, NULL);\012    narra_task_retain(task);\012    later->handle = task;\012    later->callback = callback;\012    narra_loop_queue(&later->h);\012    // Nobody holds the handle of this task: the loop does until it runs.\012    narra_task_release(&later->h);\012    return;\012  }\012  if (task->last_callback) {\012    task->last_callback->next = callback;\012  } else {\012    task->callbacks = callback;\012  }\012  task->last_callback = callback;\012}\012\012// Marks an unfinished task cancelled and drops its callbacks. Exit calls this\012// for every task, then finishes the waits itself in timer order.\012static bool narra_task_mark_cancelled(narra_task* task) {\012  if (task->done || task->cancelled) return false;\012  task->cancelled = true;\012  narra_task_run_callbacks(task, narra_task_take_callbacks(task), false);\012  return true;\012}\012\012// Async.cancel: marks the task and wakes its timer, descriptor or idle wait,\012// which then gives Err(AsyncError.Cancelled). A wait on another task's handle\012// goes on (D109 item 8).\012static void narra_task_cancel(narra_task* task) {\012  if (narra_task_mark_cancelled(task)) narra_loop_cancel_wait(task);\012}\012\012// Async.all takes each handle it was given as observed until it has awaited it.\012static void narra_task_observe(narra_task* task) {\012  task->observers++;\012}\012\012static void narra_task_unobserve(narra_task* task) {\012  task->observers--;\012}\012\012// Whether Async.peek gives the value: the task finished and was not cancelled.\012static bool narra_task_finished(narra_task* task) {\012  return task->done && !task->cancelled;\012}\012\012// The body has returned: it already released its locals, and the value is in\012// its slot. The waiters become ready, the callbacks run unless the task was\012// cancelled, and the loop drops its reference, which may free the frame, so\012// nothing reads the task after this call.\012static void narra_task_finish(narra_task* task) {\012  task->done = true;\012  task->state = -1;\012  // The list is built by pushing at the front, so it is reversed to wake the\012  // waiters in the order they started to wait.\012  narra_task* reversed = NULL;\012  while (task->waiters) {\012    narra_task* waiter = task->waiters;\012    task->waiters = waiter->next_waiter;\012    waiter->next_waiter = reversed;\012    reversed = waiter;\012  }\012  while (reversed) {\012    narra_task* waiter = reversed;\012    reversed = waiter->next_waiter;\012    waiter->next_waiter = NULL;\012    waiter->awaited = NULL;\012    narra_loop_queue(waiter);\012    narra_task_release(waiter);\012  }\012  narra_task_run_callbacks(task, narra_task_take_callbacks(task), !task->cancelled);\012  narra_loop_remove(task);\012  narra_task_release(task);\012}\012\012// Async.race: a bare task whose value is the index of the first handle to\012// finish. A watcher task waits on each unfinished handle and sets the index\012// if no other handle came first. Once the index is set, the other watchers\012// leave their handles' waiter lists and are freed, so a race decided early\012// leaves nothing behind on a handle that stays pending.\012typedef struct narra_task_watcher narra_task_watcher;\012\012typedef struct narra_task_winner {\012  narra_task h;\012  int64_t value;\012  // The watchers still in the race; this list holds no reference.\012  narra_task_watcher* watchers;\012} narra_task_winner;\012\012struct narra_task_watcher {\012  narra_task h;\012  narra_task* winner;\012  int64_t index;\012  narra_task_watcher* next_watcher;\012  narra_task_watcher* previous_watcher;\012};\012\012// Not narra_task_release_nothing: the loop takes a task with that release for\012// an idle handle, and a cancel must not finish a winner.\012static void narra_task_winner_release(narra_task* task) {\012  (void)task;\012}\012\012static narra_task* narra_task_winner_new(void) {\012  narra_task_winner* winner = narra_alloc(sizeof(narra_task_winner));\012  memset(winner, 0, sizeof(narra_task_winner));\012  narra_task_init(&winner->h, NULL, narra_task_winner_release, &winner->value);\012  return &winner->h;\012}\012\012// Takes a watcher off its winner's list.\012static void narra_task_unlist_watcher(narra_task_watcher* watcher) {\012  narra_task_winner* winner = (narra_task_winner*)watcher->winner;\012  if (watcher->previous_watcher) {\012    watcher->previous_watcher->next_watcher = watcher->next_watcher;\012  } else if (winner->watchers == watcher) {\012    winner->watchers = watcher->next_watcher;\012  }\012  if (watcher->next_watcher) watcher->next_watcher->previous_watcher = watcher->previous_watcher;\012  watcher->next_watcher = NULL;\012  watcher->previous_watcher = NULL;\012}\012\012// Ends a watcher that lost: it leaves the waiter list of its handle and the\012// loop, and both drop their references, which frees it.\012static void narra_task_drop_watcher(narra_task_watcher* watcher) {\012  narra_task* task = &watcher->h;\012  narra_task* handle = task->awaited;\012  narra_task** link = &handle->waiters;\012  while (*link && *link != task) link = &(*link)->next_waiter;\012  if (*link) *link = task->next_waiter;\012  task->awaited = NULL;\012  task->next_waiter = NULL;\012  task->done = true;\012  task->state = -1;\012  narra_loop_remove(task);\012  narra_task_release(task);\012  narra_task_release(task);\012}\012\012static void narra_task_settle(narra_task* winner, int64_t index) {\012  if (winner->done) return;\012  *(int64_t*)winner->value = index;\012  // The winner stays alive while the watchers that hold it go.\012  narra_task_retain(winner);\012  narra_task_winner* frame = (narra_task_winner*)winner;\012  while (frame->watchers) {\012    narra_task_watcher* watcher = frame->watchers;\012    narra_task_unlist_watcher(watcher);\012    // A watcher already queued ends when it resumes.\012    if (watcher->h.awaited) narra_task_drop_watcher(watcher);\012  }\012  narra_task_finish(winner);\012  narra_task_release(winner);\012}\012\012static void narra_task_watcher_resume(narra_task* task) {\012  narra_task_watcher* watcher = (narra_task_watcher*)task;\012  narra_task_unlist_watcher(watcher);\012  narra_task_settle(watcher->winner, watcher->index);\012  narra_task_finish(task);\012}\012\012static void narra_task_watcher_release(narra_task* task) {\012  narra_task_watcher* watcher = (narra_task_watcher*)task;\012  narra_task_unlist_watcher(watcher);\012  narra_task_release(watcher->winner);\012}\012\012static void narra_task_watch(narra_task* winner, narra_task* handle, int64_t index) {\012  if (winner->done) return;\012  if (handle->done) {\012    narra_task_settle(winner, index);\012    return;\012  }\012  narra_task_watcher* watcher = narra_alloc(sizeof(narra_task_watcher));\012  memset(watcher, 0, sizeof(narra_task_watcher));\012  narra_task_init(&watcher->h, narra_task_watcher_resume, narra_task_watcher_release, NULL);\012  narra_task_retain(winner);\012  watcher->winner = winner;\012  watcher->index = index;\012  narra_task_winner* frame = (narra_task_winner*)winner;\012  watcher->next_watcher = frame->watchers;\012  if (frame->watchers) frame->watchers->previous_watcher = watcher;\012  frame->watchers = watcher;\012  narra_task_wait(&watcher->h, handle);\012  // Nobody holds the watcher's handle: the loop and the waiter list do.\012  narra_task_release(&watcher->h);\012}\012\012// Part of the leak check, called at exit with the unfinished tasks: a watcher\012// whose race is decided must have left the loop. Exit would free it, so only\012// this check sees one that stayed.\012static void narra_task_check_watchers(narra_task* live) {\012  if (!getenv(\"NARRA_CHECK_LEAKS\")) return;\012  int64_t stale = 0;\012  for (narra_task* task = live; task; task = task->next_live) {\012    if (task->resume == narra_task_watcher_resume) {\012      narra_task_watcher* watcher = (narra_task_watcher*)task;\012      if (watcher->winner->done) stale++;\012    }\012  }\012  if (stale != 0) {\012    fflush(stdout);\012    fprintf(stderr, \"leak check: %\" PRId64 \" race watchers outlived their race\\n\", stale);\012    exit(102);\012  }\012}\012\012// Async generators (D110 items 1, 4 and 5). A stream is a task frame whose\012// header is followed by narra_stream_part (emitasyncgenerators.nra). Each\012// Async.next makes a step, a bare task { narra_step s; Option<T> value; }\012// that the stream's step function allocates holding None. The body runs only\012// while a step is pending: a yield fills the first pending step, and the end\012// of the body finishes every pending one with its None.\012//\012// Who holds a stream: each copy, each pending step, and the loop while the\012// body runs or waits. A stream parked at a yield with no step pending, or not\012// started yet, is out of the loop's list of live tasks, so dropping its last\012// copy frees it through its release function.\012typedef struct narra_step narra_step;\012struct narra_step {\012  narra_task h;\012  // The next pending step of the same stream.\012  narra_step* next_step;\012  // Set when a yield filled the value; a step finished by the end of the\012  // body keeps its None.\012  bool filled;\012};\012\012typedef struct narra_stream_part {\012  narra_task* (*make_step)(void);\012  narra_step* first_step;\012  narra_step* last_step;\012  bool parked;\012} narra_stream_part;\012\012typedef struct narra_stream {\012  narra_task h;\012  narra_stream_part s;\012} narra_stream;\012\012// Fills the header of a new stream frame: one reference, for the copy the\012// call returns. The stream starts parked and runs nothing.\012static void narra_stream_init(\012  narra_task* task,\012  void (*resume)(narra_task*),\012  void (*release)(narra_task*),\012  narra_task* (*make_step)(void)\012) {\012  narra_stream* stream = (narra_stream*)task;\012  task->rc = 1;\012  task->state = 0;\012  task->resume = resume;\012  task->release = release;\012  task->value = NULL;\012  stream->s.make_step = make_step;\012  stream->s.parked = true;\012}\012\012// A parked stream joins the loop's list again, with the loop's reference, and\012// runs inline until it yields, ends or waits. Its cancel state is its own, not\012// that of the task that asked for the step.\012static void narra_stream_run(narra_task* task) {\012  narra_stream* stream = (narra_stream*)task;\012  bool cancelled = task->cancelled;\012  bool started_cancelled = task->started_cancelled;\012  stream->s.parked = false;\012  narra_loop_add(task);\012  task->cancelled = task->cancelled || cancelled;\012  task->started_cancelled = started_cancelled;\012  narra_task_retain(task);\012  narra_task* previous = narra_loop_enter(task);\012  task->resume(task);\012  narra_loop_leave(previous);\012}\012\012// Async.next: a new step. On a stream that has ended it is finished at once\012// with None. Otherwise it waits in the FIFO, holding a reference to the\012// stream, and a parked stream runs now to serve it.\012static narra_task* narra_stream_next(narra_task* task) {\012  narra_stream* stream = (narra_stream*)task;\012  narra_task* handle = stream->s.make_step();\012  if (task->done) {\012    narra_task_finish(handle);\012    return handle;\012  }\012  narra_step* step = (narra_step*)handle;\012  handle->is_step = true;\012  narra_task_retain(task);\012  handle->awaited = task;\012  if (stream->s.last_step) {\012    stream->s.last_step->next_step = step;\012  } else {\012    stream->s.first_step = step;\012  }\012  stream->s.last_step = step;\012  if (stream->s.parked) narra_stream_run(task);\012  return handle;\012}\012\012// Takes the first pending step off the FIFO, for a yield or the end. The\012// body runs only while a step is pending, so a yield always finds one.\012static narra_task* narra_stream_take(narra_task* task) {\012  narra_stream* stream = (narra_stream*)task;\012  narra_step* step = stream->s.first_step;\012  if (!step) return NULL;\012  stream->s.first_step = step->next_step;\012  if (!stream->s.first_step) stream->s.last_step = NULL;\012  step->next_step = NULL;\012  return &step->h;\012}\012\012// Drops a step's reference to its stream (a step's release function, and\012// the end of a pending step).\012static void narra_step_drop(narra_task* task) {\012  narra_task* stream = task->awaited;\012  if (!stream || !task->is_step) return;\012  task->awaited = NULL;\012  narra_task_release(stream);\012}\012\012// Finishes a step taken off the FIFO: its awaiters become ready. The loop\012// still holds the stream while its body runs, so the release frees nothing.\012static void narra_stream_give(narra_task* task, bool filled) {\012  ((narra_step*)task)->filled = filled;\012  narra_task* stream = task->awaited;\012  task->awaited = NULL;\012  narra_task_finish(task);\012  narra_task_release(stream);\012}\012\012static bool narra_step_filled(narra_task* task) {\012  return ((narra_step*)task)->filled;\012}\012\012// After a yield: with steps pending, the stream serves the next one on a\012// later loop turn; with none it parks and the loop drops its reference,\012// which frees a stream nobody holds. Nothing reads the frame after this call.\012static void narra_stream_pause(narra_task* task) {\012  narra_stream* stream = (narra_stream*)task;\012  if (stream->s.first_step) {\012    narra_loop_queue(task);\012    return;\012  }\012  stream->s.parked = true;\012  narra_loop_remove(task);\012  narra_task_release(task);\012}\012\012// The end of the body: every pending step gives None, then the stream\012// finishes and the loop drops its reference.\012static void narra_stream_end(narra_task* task) {\012  narra_task* step = narra_stream_take(task);\012  while (step) {\012    narra_stream_give(step, false);\012    step = narra_stream_take(task);\012  }\012  narra_task_finish(task);\012}\012"};
